// work.visit.record — generated by `pnpm gen:command work record-visit`. Fill in the input, the change and the
// audit record. SOP rules go in ../rules (pnpm gen:rule), table access in ../repository.ts (02-architecture §3).
import { z } from 'zod';
import { defineCommand } from '../../kernel/index.ts';
import { workPermissions } from '../permissions.ts';

export const recordVisit = defineCommand({
  name: 'work.visit.record',
  permission: workPermissions.recordVisit,
  input: z.object({ id: z.uuid() }),
  describe: (i) => `Record a site visit and its action items the same day (SOP-DEL-03 §5.1) ${i.id}`,
  handle: (_ctx, i) =>
    Promise.resolve({
      result: { id: i.id },
      audit: { objectType: 'visit', objectId: i.id, clientId: null, before: null, after: null },
    }),
});
